        "queue-master-L00003"
      ]
    },
    {
      "claim": "Orders service timed out when calling inventory (or payments), resulting in a TimeoutException and an IllegalStateException about being unable to create an order.",
      "status": "confirmed",
      "cites": [
        "orders-L000aa",
        "orders-L000ac"
      ]
    },
    {
      "claim": "Front-end returned a 500 error to the user with the message 'Unable to create order due to timeout from one of the services.'",
      "status": "confirmed",
